  -- beginner final ord 9
  select case
           when prompt = 'One liquid reading is 0.984776 and another on the same stream is 0.984858. What separates them?' and options = '["The first is the correction at the stated viscosity and the second is the correction at the clamp itself.", "The first is the correction the loop converged on and the second is what a single pass would have used.", "The first is the correction this engine returned and the second is the correction the validation oracle derived.", "The first is the correction on the converged area and the second the correction on the inviscid one."]'::jsonb and answer_index = 1 and explanation is not distinct from 'Each figure carries its own Reynolds number, 17546.394776 for the shortcut and 17412.317969 for the loop. The shortcut is what a hand calculation usually does, and the digest prints the ratio between the two areas they imply.' then 'old'
           when prompt = 'One liquid reading is 0.984776 and another on the same stream is 0.984858. What separates them?' and options = '["The first is the correction at the stated viscosity and the second is the correction at the clamp itself.", "The first is the correction the loop converged on and the second is what a single pass would have used.", "The first is the correction this engine returned and the second is the correction the validation oracle derived.", "The first is the correction on the converged area and the second the correction on the inviscid one."]'::jsonb and answer_index = 1 and explanation is not distinct from 'Each figure carries its own Reynolds number, 17546.394776 for the shortcut and 17412.317969 for the loop. The shortcut is what a hand calculation usually does, and the course prints the ratio between the two areas they imply.' then 'new'
           else 'other' end
