    from public.academy_quiz_questions where app_slug = 'relief' and tier = 'beginner' and scope = 'final' and module_key is not distinct from null and ord = 9;
  if v_state is null then raise exception 'digest-copy recut, relief refused: no row for beginner final ord 9'; end if;
  if v_state = 'other' then raise exception 'digest-copy recut, relief refused: beginner final ord 9 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'One liquid reading is 0.984776 and another on the same stream is 0.984858. What separates them?', options = '["The first is the correction at the stated viscosity and the second is the correction at the clamp itself.", "The first is the correction the loop converged on and the second is what a single pass would have used.", "The first is the correction this engine returned and the second is the correction the validation oracle derived.", "The first is the correction on the converged area and the second the correction on the inviscid one."]'::jsonb, explanation = 'Each figure carries its own Reynolds number, 17546.394776 for the shortcut and 17412.317969 for the loop. The shortcut is what a hand calculation usually does, and the course prints the ratio between the two areas they imply.'
